    /// These callbacks validate only bounded generated metadata/FS ordering.
    /// Portable slot/SDK correctness is covered by the separate real SDK suite.
    private func slotIO(write: @escaping (Int32, UnsafeRawPointer, Int) -> Int = { Darwin.write($0, $1, $2) },
                        sync: @escaping (Int32) -> Int32 = Darwin.fsync,
                        rename: @escaping (Int32, String, String) -> Int32 = { Darwin.renameat($0, $1, $0, $2) },
                        directorySync: @escaping (Int32) -> Int32 = Darwin.fsync,
                        read: @escaping (Int32, UnsafeMutableRawPointer, Int) -> Int = { Darwin.read($0, $1, $2) }) -> RecordingCatalogue.CheckpointIO {
        RecordingCatalogue.CheckpointIO(write: write, synchronize: sync, rename: rename, synchronizeDirectory: directorySync, read: read)
    }
    private func installSlot(_ owner: RecordingCatalogue.AppendWriter, sequence: UInt32, end: UInt64,
                             value: UInt8 = 1, validate: (Data) throws -> Void = { _ in }) throws -> RecordingCatalogue.AppendWriter.InstalledMetadataReceipt {
        let bindings = try owner.bindings()
        return try owner.appendCheckpointFragment(Data([value]), expectedEnd: end, sequence: sequence,
            checkpointBytes: Data(repeating: value, count: 545), initialLength: 1,
            initialHash: Data(SHA256.hash(data: Data([9]))), expectedBindings: bindings, validateInstalled: validate)
    }
    func testCheckpointCompositeOrderIncludesDecodeBeforeActualReadbackClose() throws {
        var events: [String] = [], active = false
        let append = appendIO(write: { fd, bytes, count in if active { events.append("append") }; return Darwin.write(fd, bytes, count) },
                              synchronize: { fd in if active { events.append("media-sync") }; return Darwin.fsync(fd) })
        let checkpoints = slotIO(write: { fd, bytes, count in events.append("temp-write"); return Darwin.write(fd, bytes, count) },
            sync: { fd in events.append("temp-sync"); return Darwin.fsync(fd) },
            rename: { fd, source, target in events.append("rename"); return Darwin.renameat(fd, source, fd, target) },
            directorySync: { fd in events.append("directory-sync"); return Darwin.fsync(fd) },
            read: { fd, bytes, count in events.append("readback"); return Darwin.read(fd, bytes, count) })
        let catalogue = try RecordingCatalogue(root: directory(), appendIO: append, checkpointIO: checkpoints,
            closeFileDescriptor: { fd in if active { events.append("close") }; return Darwin.close(fd) })
        defer { try? catalogue.close() }
        let owner = try catalogue.beginAppend(identity: appendIdentity(catalogue), payloadLimit: 1024)
        _ = try owner.writeInitial(Data([9])); active = true
        let receipt = try installSlot(owner, sequence: 1, end: 2) { bytes in
            events.append("validate")
            XCTAssertEqual(bytes, Data(repeating: 1, count: 545))
            self.assertFailure(.busy) { _ = try owner.closeIncomplete() }
            self.assertFailure(.busy) { _ = try owner.appendFragment(Data([2]), expectedEnd: 3) }
        }
        events.append("returned"); active = false
        XCTAssertEqual(events, ["append", "media-sync", "temp-write", "temp-sync", "close", "rename", "directory-sync", "readback", "validate", "close", "returned"])
        XCTAssertTrue(owner.confirms(receipt)); XCTAssertEqual(receipt.slot, 1)
        XCTAssertFalse(owner.cleanupComplete); assertFailure(.busy) { try catalogue.close() }
        _ = try owner.closeIncomplete()
    }
