                if fault && stage == 0 {
                    if !partial { partial = true; return Darwin.write(fd, bytes, min(7, count)) }
                    errno = ENOSPC; return -1
                }
                return Darwin.write(fd, bytes, count)
            }, sync: { fd in if fault && stage == 1 { errno = EIO; return -1 }; return Darwin.fsync(fd) },
               rename: { fd, source, target in if fault && stage == 2 { errno = EIO; return -1 }; return Darwin.renameat(fd, source, fd, target) },
               directorySync: { fd in if fault && stage == 3 { errno = EIO; return -1 }; return Darwin.fsync(fd) },
               read: { fd, bytes, count in
                   if fault && stage == 4 { errno = EIO; return -1 }
                   if fault && stage == 5 { return 0 }
                   return Darwin.read(fd, bytes, count)
               })
            let root = directory("checkpoint-fault\(stage)"), catalogue = try RecordingCatalogue(root: root, appendIO: appendIO(), checkpointIO: checkpoints)
            defer { try? catalogue.close() }
            let identity = try appendIdentity(catalogue), owner = try catalogue.beginAppend(identity: identity, payloadLimit: 1024)
            _ = try owner.writeInitial(Data([9])); _ = try installSlot(owner, sequence: 1, end: 2); fault = true
