            XCTAssertEqual(try Data(contentsOf: root.appendingPathComponent("Sapflow-\(identity.segmentID).checkpoint.1")), Data(repeating: 1, count: 545))
            XCTAssertEqual(try Data(contentsOf: root.appendingPathComponent(identity.filename)), Data([9, 1, 2]))
            XCTAssertTrue(catalogue.cleanupRetained); XCTAssertFalse(owner.cleanupComplete)
            _ = try owner.closeIncomplete()
        }
    }
